  font-weight: 500;
  opacity: 0.8;
  animation: blink 1.5s ease-in-out infinite;
}

/* 脉冲边框动画 */
@keyframes pulse-border {
  0%,
  100% {
    border-color: rgba(255, 149, 0, 0.3);
    box-shadow: 0 0 0 0 rgba(255, 149, 0, 0.1);
  }
  50% {
    border-color: rgba(255, 149, 0, 0.6);
    box-shadow: 0 0 0 4px rgba(255, 149, 0, 0.1);
  }
}

/* 闪烁提示动画 */
@keyframes blink {
  0%,
  100% {
    opacity: 0.8;
  }
  50% {
    opacity: 1;
  }
}

/* 标题与图标容器 */
.title-with-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* 标题和状态在同一行 */
.title-with-icon .story-title {
  margin-right: 12px;
}

.title-with-icon .story-status {
  margin: 0;
  flex-shrink: 0;
}

/* 未开始状态的图标 */
.no-plot-icon {
  font-size: 24px;
  color: #ff9500;
  animation: bounce 2s ease-in-out infinite;
  flex-shrink: 0;
}

@keyframes bounce {
  0%,
  20%,
  50%,
  80%,
  100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-5px);
  }
  60% {
    transform: translateY(-3px);
  }
}

.story-title-wrapper {
  text-align: center;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
  transition: var(--transition);
}

.story-title-wrapper:hover {
  background: rgba(0, 122, 255, 0.1);
}

.story-title {
  font-size: 20px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.3;
}

.story-status {
  font-size: 14px;
  font-weight: 500;
  margin: 0;
  white-space: nowrap;
}

.story-progress {
  font-size: 13px;
  font-weight: 500;
  margin: 4px 0 0 0;
  padding: 6px 12px;
  background: rgba(0, 122, 255, 0.1);
  border-radius: 8px;
  border-left: 3px solid var(--primary-color);
  color: var(--primary-color);
  line-height: 1.3;
}

/* 状态和进度的联合显示容器 */
.story-status-container {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  justify-content: center;
  margin-top: 4px;
  width: 100%;
}

.story-status-container .story-progress {
  margin: 0;
  flex: 1;
  min-width: 200px;
}

/* 小屏幕下的优化 */
@media (max-width: 480px) {
  .story-status-container {
    flex-direction: column;
    gap: 4px;
  }

  .story-status-container .story-progress {
    min-width: auto;
    width: 100%;
  }
}

.click-hint {
  font-size: 12px;
  color: var(--text-secondary);
  opacity: 0.6;
  margin: 0;
  font-style: italic;
  transition: var(--transition);
}

.current-story-display:hover .click-hint {
  opacity: 0.8;
}

/* 回到当前剧情按钮 */
.back-to-current-btn {
  width: 32px;
  height: 32px;
  border: none;
  background: var(--primary-color);
  border-radius: 50%;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 14px;
  box-shadow: 0 2px 8px rgba(0, 122, 255, 0.3);
  flex-shrink: 0;
  margin-left: 8px;
}

.back-to-current-btn:hover {
  background: #0056cc;
  transform: scale(1.1);
  box-shadow: 0 4px 12px rgba(0, 122, 255, 0.4);
}

.back-to-current-btn:active {
  transform: scale(0.95);
}

/* 操作按钮区域 */
.action-buttons {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.action-btn {
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 20px;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  background: rgba(120, 120, 128, 0.16);
  color: var(--text-primary);
}

.action-btn:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.05);
}

.action-btn.primary {
  background: var(--primary-color);
  color: white;
}

.action-btn.primary:hover {
  background: #0056cc;
  transform: scale(1.05);
}

/* 主要按钮样式 */
.control-btn.primary {
  background: var(--primary-color);
  color: white;
  box-shadow: var(--shadow-light);
}

.control-btn.primary:hover {
  background: #0056cc;
  transform: translateY(-1px);
  box-shadow: var(--shadow-medium);
}

.control-btn.primary:active {
  transform: translateY(0);
  background: #004499;
}

/* 次要按钮样式 */
.control-btn.secondary {
  background: var(--background-color);
  color: var(--primary-color);
  border: 1px solid var(--border-color);
}

.control-btn.secondary:hover {
  background: #e5e5ea;
  transform: translateY(-1px);
}

.control-btn.secondary:active {
  transform: translateY(0);
  background: #d1d1d6;
}

/* 禁用状态 */
.control-btn:disabled {
  background: var(--border-color) !important;
  color: var(--text-secondary) !important;
  cursor: not-allowed !important;
  transform: none !important;
  box-shadow: none !important;
}

/* 按钮图标 */
.btn-icon {
  font-size: 18px;
  line-height: 1;
}

/* 弹出面板通用样式 - 向上弹出的iPhone风格 */
.popup-panel {
  background: var(--surface-color);
  border-radius: var(--border-radius);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
  margin: 0 0 2px 0; /* 进一步减少边距 */
  border: 0.5px solid rgba(0, 0, 0, 0.1);
  overflow: hidden;
  backdrop-filter: blur(20px);
  transform-origin: bottom;
  /* 默认隐藏在下方 */
  transform: translateY(20px) scaleY(0.8);
  opacity: 0;
  transition: none; /* 移除动画效果 */
  max-height: 0;
}

/* 显示状态的弹出面板 */
.popup-panel.show {
  transform: translateY(0) scaleY(1);
  opacity: 1;
  max-height: calc(100vh - 100px); /* 为导航区域留出空间 */
}

/* 剧情详情面板特殊高度设置 */
.story-detail-section.popup-panel.show {
  max-height: calc(100vh - 80px); /* 剧情详情需要更多空间 */
}

/* 小屏幕下的弹出面板 - 允许更大高度 */
@media (max-width: 480px) {
  .popup-panel {
    margin: 0; /* 小屏幕下无边距，充分利用空间 */
  }

  .popup-panel.show {
    max-height: calc(100vh - 120px); /* 留出导航区域的空间 */
  }

  /* 剧情详情面板在小屏幕下显示更多内容 */
  .story-detail-section.popup-panel.show {
    max-height: calc(100vh - 60px);
  }

  .story-detail-section .detail-content {
    max-height: calc(100vh - 120px);
  }
}

/* 展开区域通用样式 - iPhone风格（继承popup-panel样式） */

.section-header {
  padding: 12px 16px;
  background: rgba(248, 248, 248, 0.95);
  backdrop-filter: blur(20px);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-header h3 {
  font-size: 16px;
  font-weight: 600;
  margin: 0;
  color: var(--text-primary);
}

.header-buttons {
  display: flex;
  gap: 8px;
  align-items: center;
}

.sort-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: rgba(120, 120, 128, 0.16);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 600;
}

.sort-btn:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.05);
}

.sort-btn.asc .btn-icon::after {
  content: '↑';
}

.sort-btn.desc .btn-icon::after {
  content: '↓';
}

.close-section-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: rgba(120, 120, 128, 0.16);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 600;
}

.close-section-btn:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.05);
}

/* 剧情列表区域 */
.story-list-container {
  max-height: 240px; /* 约3个选项的高度 */
  overflow-y: auto;
  padding: 8px 12px 12px;
}

/* 剧情列表项 - iPhone风格 */
.story-item {
  padding: 8px 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: var(--transition);
  margin-bottom: 4px;
  border: none;
  background: rgba(120, 120, 128, 0.08);
}

.story-item:hover {
  background: rgba(0, 122, 255, 0.1);
  transform: scale(1.01);
}

.story-item.current {
  background: rgba(0, 122, 255, 0.15);
  border: 1px solid var(--primary-color);
}

.story-item-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.story-item-title {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
  line-height: 1.2;
  color: var(--text-primary);
}

.story-item-location {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1.2;
}

.story-item-progress {
  font-size: 11px;
  color: var(--primary-color);
  font-weight: 500;
  margin: 0;
  line-height: 1.2;
}

/* 剧情详情区域 - iPhone风格 */
.detail-content {
  padding: 16px;
  background: var(--surface-color);
  max-height: 450px;
  overflow-y: auto;
}

/* 设置面板样式 */
.settings-content {
  padding: 16px;
  background: var(--surface-color);
}

/* 旧的内联按钮样式 - 已废弃，改用顶部按钮 */
.detail-actions-inline {
  display: none !important; /* 隐藏旧的底部按钮 */
}

/* 旧的内联按钮子样式 - 已废弃 */

/* 顶部操作按钮区域 - 彻底解决遮挡问题 */
.detail-actions-top {
  padding: 16px;
  background: rgba(248, 248, 248, 0.98);
  backdrop-filter: blur(20px);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
  display: flex;
  gap: 12px;
